"""Date-window membership for the date_window fixture."""

from __future__ import annotations


def in_any_window(target_date: str, windows: list[tuple[str, str]]) -> bool:
    """Return whether target_date falls inside any date window."""

    # Parse and validate target_date
    target = _parse_and_validate_date(target_date)

    # Parse, validate, and check all windows
    for start_str, end_str in windows:
        start = _parse_and_validate_date(start_str)
        end = _parse_and_validate_date(end_str)

        # Check that start <= end
        if start > end:
            raise ValueError(f"Invalid window: start ({start_str}) > end ({end_str})")

        # Check if target is within this window (inclusive on both ends)
        if start <= target <= end:
            return True

    return False


def _parse_and_validate_date(date_str: str) -> tuple[int, int, int]:
    """Parse and validate a date string in YYYY-MM-DD format.

    Returns a tuple (year, month, day) for easy comparison.
    Raises ValueError if the date is malformed or impossible.
    """
    # Check format: must be exactly YYYY-MM-DD
    if not isinstance(date_str, str) or len(date_str) != 10:
        raise ValueError(f"Invalid date format: {date_str}")

    if date_str[4] != '-' or date_str[7] != '-':
        raise ValueError(f"Invalid date format: {date_str}")

    try:
        year_str, month_str, day_str = date_str.split('-')
        year = int(year_str)
        month = int(month_str)
        day = int(day_str)
    except (ValueError, IndexError):
        raise ValueError(f"Invalid date format: {date_str}")

    # Validate format: no leading zeros except where required, must be 4, 2, 2 digits
    if len(year_str) != 4 or len(month_str) != 2 or len(day_str) != 2:
        raise ValueError(f"Invalid date format: {date_str}")

    # Check if month is valid (1-12)
    if month < 1 or month > 12:
        raise ValueError(f"Invalid month in date: {date_str}")

    # Check if day is valid for the given month and year
    if day < 1:
        raise ValueError(f"Invalid day in date: {date_str}")

    # Days in each month (non-leap year)
    days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    # Check for leap year
    is_leap = _is_leap_year(year)
    if is_leap:
        days_in_month[1] = 29

    if day > days_in_month[month - 1]:
        raise ValueError(f"Invalid day in date: {date_str}")

    return (year, month, day)


def _is_leap_year(year: int) -> bool:
    """Check if a year is a leap year."""
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    if year % 4 == 0:
        return True
    return False
